from itertools import combinations, product


def find_all_arb(contracts, quotes):
    """contracts: {name: [payoff on faces 1..6]};
    quotes: {name: (bid, ask)}. Try every set of 1 to 3
    contracts, each bought once (at the ask) or sold once
    (at the bid). Score each by its profit on the worst
    face (payoff plus cash) and keep those above 0. Return (profit, trades) for the
    best: highest profit, then fewest trades, then the
    first in sorted order; trades is a sorted tuple of
    (name, "buy" or "sell"). With none: (Fr(0), ())."""
    best = None
    names = sorted(quotes)
    for k in (1, 2, 3):
        for combo in combinations(names, k):
            for sides in product((1, -1), repeat=k):
                net = [sum(s * contracts[n][f] for n, s in zip(combo, sides))
                       for f in range(6)]
                cash = sum(-quotes[n][1] if s > 0 else quotes[n][0]
                           for n, s in zip(combo, sides))
                profit = min(net) + cash
                if profit <= 0:
                    continue
                trades = tuple(sorted((n, "buy" if s > 0 else "sell")
                                      for n, s in zip(combo, sides)))
                key = (-profit, len(trades), trades)
                if best is None or key < best[0]:
                    best = (key, (profit, trades))
    return best[1] if best else (Fr(0), ())
